import {mkdir, readFile, rename, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

import {format, resolveConfig} from 'prettier';

import {colorMapping} from './otus-color-mapping.mjs';

export async function generateOtusColors(root) {
    const mapping = await colorMapping(root);
    const lines = [
        '// Generated by projects/styles/scripts/generate-otus-colors.mjs. Do not edit by hand.',
        '// Taiga roles and component references are preserved; OTUS supplies their values.',
        '.otus-color-primitives() {',
        ...mapping.primitives.map(
            (token) =>
                `    ${token.cssVariable}: ${token.value.toLowerCase().replace(/^#([a-f\d])\1([a-f\d])\2([a-f\d])\3$/, '#$1$2$3')};`,
        ),
        '}',
    ];

    for (const school of mapping.schoolAssignments) {
        lines.push('', `.otus-color-school('${school.id}') {`);

        for (const theme of mapping.modes.themes) {
            for (const row of mapping.mappings) {
                const target = row.variants[theme].schools[school.id];

                if (!target.alias) {
                    lines.push(`    --t-otus-${theme}-${row.tui.slice(6)}: ${target.css};`);
                }
            }
        }

        lines.push('}');
    }

    for (const theme of mapping.modes.themes) {
        lines.push('', `.otus-color-theme('${theme}') {`);

        for (const row of mapping.mappings) {
            const target = row.variants[theme].schools[mapping.schoolAssignments[0].id];
            const value = target.alias ? `var(${target.alias})` : `var(--t-otus-${theme}-${row.tui.slice(6)})`;

            lines.push(`    ${row.tui}: ${value};`);
        }

        const localOverride = mapping.contextOverrides.find((item) => item.theme === theme);
        const checkedNegative = localOverride?.css ?? `var(--t-otus-${theme}-status-negative)`;

        lines.push(`    --t-otus-checked-negative: ${checkedNegative};`, '}');
    }

    lines.push('', '.otus-color-modes() {');

    for (const school of mapping.schoolAssignments) {
        if (school !== mapping.schoolAssignments[0]) {
            lines.push('');
        }

        lines.push(
            `    &[data-brand='${school.id}'],`,
            `    & [data-brand='${school.id}'] {`,
            `        .otus-color-school('${school.id}');`,
            "        .otus-color-theme('light');",
            '    }',
        );
    }

    lines.push('', '    @media screen {');

    for (const theme of mapping.modes.themes) {
        for (const school of mapping.schoolAssignments) {
            lines.push(
                '',
                `    &[data-brand='${school.id}'][tuiTheme='${theme}'],`,
                `    & [data-brand='${school.id}'][tuiTheme='${theme}'],`,
                `    :where([tuiTheme='${theme}']) &[data-brand='${school.id}'],`,
                `    & :where([tuiTheme='${theme}']) [data-brand='${school.id}'] {`,
                `        .otus-color-theme('${theme}');`,
                '    }',
            );
        }
    }

    lines.push('    }');

    for (const override of mapping.contextOverrides) {
        lines.push(
            '',
            `    &${override.selector},`,
            `    & ${override.selector} {`,
            '        // This private inherited alias follows the nearest theme without changing Taiga roles.',
            `        ${override.token}: var(--t-otus-checked-negative);`,
            '    }',
        );
    }

    lines.push('}', '');

    const filename = path.join(root, 'projects/styles/mixins/theme/otus-colors.generated.less');
    const content = await format(lines.join('\n').replaceAll('{\n\n', '{\n'), {
        ...(await resolveConfig(filename)),
        filepath: filename,
    });
    const previous = await readFile(filename, 'utf8').catch(() => '');

    if (content !== previous) {
        await mkdir(path.dirname(filename), {recursive: true});
        await writeFile(`${filename}.tmp`, content);
        await rename(`${filename}.tmp`, filename);
    }

    return mapping;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    await generateOtusColors(fileURLToPath(new URL('../../../', import.meta.url)));
}
